/* Copyright © 2026 上海如静知华信息科技有限公司 · https://www.zhuatech.cn/ */package cn.zhuatech.syntheticdata.model;import jakarta.persistence.*;import java.time.Instant;@Entity@Table(name="generation_audit",uniqueConstraints=@UniqueConstraint(name="uk_generation_request",columnNames="request_id"))public class GenerationAudit{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="request_id",nullable=false,length=80)private String requestId;@Column(nullable=false,length=30)private String decision;@Column(nullable=false)private int rowCount;@Column(nullable=false,length=20)private String riskLevel;@Column(nullable=false,length=500)private String summary;@Column(nullable=false,length=80)private String createdBy;@Column(nullable=false)private Instant createdAt;protected GenerationAudit(){}public GenerationAudit(String r,String d,int n,String risk,String s,String b){requestId=r;decision=d;rowCount=n;riskLevel=risk;summary=s;createdBy=b;createdAt=Instant.now();}public Long getId(){return id;}public String getRequestId(){return requestId;}public String getDecision(){return decision;}public int getRowCount(){return rowCount;}public String getRiskLevel(){return riskLevel;}public String getSummary(){return summary;}public String getCreatedBy(){return createdBy;}public Instant getCreatedAt(){return createdAt;}}
